      "На среднем огне разогрейте сковороду с одной столовой ложкой растительного масла. Обжарьте грибы до золотистой корочки и переложите на тарелку.",
      "Добавьте оставшуюся ложку масла и обжарьте говядину до золотистой корочки. Переложите мясо к грибам.",
      "На той же сковороде обжарьте лук и чеснок до мягкости.",
      "В форму для запекания выложите половину грибов, сверху — мясо и картофель. Добавьте обжаренные лук и чеснок, затем распределите оставшиеся грибы.",
      "Посолите и поперчите. Запекайте в духовке, разогретой до 180 °C, около 45–50 минут, пока картофель не станет мягким и золотистым.",
      "Перед подачей украсьте зеленью."
