      "На той же сковороде на сильном огне быстро обжарьте свинину до румянца с одной-двух сторон, затем переложите к овощам.",
      "Посолите и приправьте смесь, перемешайте. На дно каждого горшочка положите по лавровому листу и измельчённому зубчику чеснока.",
      "Разложите мясо с овощами по горшочкам, заполняя их примерно на две трети.",
      "Смешайте сметану с томатной пастой и водой. Разлейте заливку по горшочкам, не доливая до краёв.",
